// Some portions generated by Claude
package org.eclipse.rdf4j.spin.function;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * A filter over a function that cannot promise repeatability must see each solution of its group exactly once:
 * relocating it into one join operand or folding it into a constant changes how many solutions pass. The oracle is the
 * same filter calling the volatile delegate directly, which already declares its volatility.
 */
class SpinFunctionFilterPlacementTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final String NS = "http://example.org/";

	private static final String COUNTER = "urn:test:spin:placement-counter";

	private static final String PREFIXES = "PREFIX spif: <http://spinrdf.org/spif#>\nPREFIX ex: <" + NS + ">\n";

	private final AtomicInteger invocations = new AtomicInteger();

	private final Function counter = new Function() {

		@Override
		public String getURI() {
			return COUNTER;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) {
			return valueFactory.createLiteral(invocations.incrementAndGet());
		}

		@Override
		public boolean mustReturnDifferentResult() {
			return true;
		}
	};

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		FunctionRegistry.getInstance().add(counter);
		repository = new SailRepository(new MemoryStore());
		try (RepositoryConnection connection = repository.getConnection()) {
			for (int i = 1; i <= 4; i++) {
				IRI subject = VF.createIRI(NS, "a" + i);
				connection.add(subject, VF.createIRI(NS, "p"), VF.createIRI(NS, "x"));
				connection.add(subject, VF.createIRI(NS, "q"), VF.createIRI(NS, "y1"));
				connection.add(subject, VF.createIRI(NS, "q"), VF.createIRI(NS, "y2"));
			}
		}
	}

	@AfterEach
	void tearDown() {
		FunctionRegistry.getInstance().remove(counter);
		repository.shutDown();
	}

	@Test
	void invokeFilterIsNotPushedIntoTheLeftSideOfAnOptional() {
		String group = "SELECT ?a ?y WHERE { ?a ex:p ?x OPTIONAL { ?a ex:q ?y } FILTER(%s <= 2) }";

		List<BindingSet> direct = evaluate(group.formatted("<" + COUNTER + ">(?a)"));
		List<BindingSet> invoked = evaluate(group.formatted("spif:invoke(<" + COUNTER + ">, ?a)"));

		assertThat(direct).hasSize(2);
		assertThat(invoked).hasSameSizeAs(direct);
	}

	@Test
	void invokeWithConstantArgumentsIsEvaluatedForEverySolution() {
		String group = "SELECT ?a WHERE { ?a ex:p ?x FILTER(%s <= 2) }";

		List<BindingSet> direct = evaluate(group.formatted("<" + COUNTER + ">()"));
		List<BindingSet> invoked = evaluate(group.formatted("spif:invoke(<" + COUNTER + ">)"));

		assertThat(direct).hasSize(2);
		assertThat(invoked).hasSameSizeAs(direct);
	}

	private List<BindingSet> evaluate(String query) {
		invocations.set(0);
		try (RepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(PREFIXES + query).evaluate());
		}
	}
}
